def transform(grid):
    out=[r[:] for r in grid]
    for i,row in enumerate(grid):
        for j,x in enumerate(row):
            if x==9: out[i][j]=row[j-1] if j else row[j+1]
    return out

def transform(grid):
    out=[r[:] for r in grid]
    for i,row in enumerate(grid):
        for j,x in enumerate(row):
            if x==9: out[i][j]=row[j+1] if j+1<len(row) else row[j-1]
    return out

def transform(grid):
    out=[]
    for row in grid:
        first=next((x for x in row if x!=9),2)
        out.append([first if x==9 else x for x in row])
    return out
